{
  "sql": "WITH product_quarterly_revenue AS (SELECT p.prod_id, p.name AS prod_name, CAST(strftime('%Y', o.order_date) AS INTEGER) AS yr, (CAST(strftime('%m', o.order_date) AS INTEGER) + 2) / 3 AS qtr, SUM(oi.qty * p.unit_price * (1 - COALESCE(oi.discount_pct, 0) / 100.0)) AS revenue FROM products p JOIN order_items oi ON p.prod_id = oi.prod_id JOIN orders o ON oi.order_id = o.order_id WHERE o.status != 'CANCELLED' GROUP BY p.prod_id, p.name, yr, qtr), indexed_revenue AS (SELECT prod_id, prod_name, yr, qtr, yr * 4 + qtr AS qtr_index, revenue FROM product_quarterly_revenue), lagged_revenue AS (SELECT curr.prod_id, curr.prod_name, curr.yr || 'Q' || curr.qtr AS current_quarter, curr.revenue AS current_revenue, prev.revenue AS previous_revenue FROM indexed_revenue curr JOIN indexed_revenue prev ON curr.prod_id = prev.prod_id AND curr.qtr_index = prev.qtr_index + 1) SELECT prod_id, prod_name, current_quarter, current_revenue, previous_revenue, ROUND(((previous_revenue - current_revenue) * 100.0 / previous_revenue), 2) AS percentage_drop FROM lagged_revenue WHERE previous_revenue > 0 AND ((previous_revenue - current_revenue) * 100.0 / previous_revenue) > 30.0"
}